// Generates the deterministic images used by the bg-image fixture.
// Run: node tests/fixtures/assets/make-assets.mjs (outputs are committed).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { PNG } from "pngjs";

const DIR = path.dirname(fileURLToPath(import.meta.url));
const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));

function quad(size, colors) {
  const png = new PNG({ width: size, height: size });
  const half = size / 2;
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const c = hex(colors[(y < half ? 0 : 2) + (x < half ? 0 : 1)]);
      const i = (y * size + x) * 4;
      png.data[i] = c[0]; png.data[i + 1] = c[1]; png.data[i + 2] = c[2]; png.data[i + 3] = 255;
    }
  return PNG.sync.write(png);
}

// Same-origin file: TL red, TR green, BL blue, BR orange.
fs.writeFileSync(path.join(DIR, "quad.png"), quad(240, ["#e6194b", "#3cb44b", "#4363d8", "#f58231"]));
// Data-URI variant: TL purple, TR cyan, BL magenta, BR lime.
const b64 = quad(240, ["#911eb4", "#42d4f4", "#f032e6", "#bfef45"]).toString("base64");
fs.writeFileSync(
  path.join(DIR, "quad-data.css"),
  `/* generated by make-assets.mjs */\n.bg-data { background-image: url(data:image/png;base64,${b64}); }\n`
);
// SVG variants (claims C01/C02): same-origin file and data-URI.
const svg = (c) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240" viewBox="0 0 240 240">` +
  `<rect x="0" y="0" width="120" height="120" fill="${c[0]}"/><rect x="120" y="0" width="120" height="120" fill="${c[1]}"/>` +
  `<rect x="0" y="120" width="120" height="120" fill="${c[2]}"/><rect x="120" y="120" width="120" height="120" fill="${c[3]}"/></svg>`;
fs.writeFileSync(path.join(DIR, "quad.svg"), svg(["#469990", "#9a6324", "#800000", "#808000"]));
fs.writeFileSync(
  path.join(DIR, "quad-svg-data.css"),
  `/* generated by make-assets.mjs */\n.bg-svg-data { background-image: url("data:image/svg+xml,${encodeURIComponent(svg(["#000075", "#aaffc3", "#e6beff", "#fabed4"]))}"); }\n`
);
console.log("assets written");
